for (const plan of additionalLessonPlans) {
  const target = modules.find((module) => module.id === plan.moduleId);
  if (!target) throw new Error(`Module not found for lesson ${plan.slug}`);
  target.lessons.push({
    id: `${plan.moduleId}-${plan.slug}`,
    moduleId: plan.moduleId,
    title: plan.title,
    eyebrow: plan.eyebrow,
    objective: plan.objective,
    duration: plan.duration,
    summary: plan.summary,
    content: plan.content,
    code: plan.code,
    exercise: plan.exercise,
    video: courseVideoRefs[plan.moduleId][plan.videoIndex % courseVideoRefs[plan.moduleId].length],
    quiz: plan.questions.map((item, index) => ({ ...item, id: `${plan.moduleId}-${plan.slug}-${index + 1}` })),
  });
}

for (const module of modules) {
  for (const lesson of module.lessons) {
    if (!lesson.video) lesson.video = courseVideoRefs[module.id][0];
  }
}

