export const allLessons = modules.flatMap((module) => module.lessons);
export const allQuestions = allLessons.flatMap((lesson) => lesson.quiz);
export const totalLessonCount = allLessons.length;
export const totalModuleCount = modules.length;
export const estimatedCourseHours = Math.max(1, Math.ceil(allLessons.reduce((total, lesson) => total + Number.parseInt(lesson.duration, 10), 0) / 60));

export function getLessonById(id?: string) {
  return allLessons.find((lesson) => lesson.id === id) ?? allLessons[0];
}

export function getModuleById(id?: string) {
  return modules.find((module) => module.id === id) ?? modules[0];
}

export function getNextLesson(lessonId: string) {
  const index = allLessons.findIndex((lesson) => lesson.id === lessonId);
  return allLessons[index + 1] ?? null;
}
